(()=>{const root=document.querySelector('#account-content'),msg=document.querySelector('#account-message');const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function api(p,method='GET',body){const r=await fetch('/api/admin/'+p,{method,headers:{'content-type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});const b=await r.json();if(!r.ok){if(r.status===401||r.status===403)window.AcademyAccess.lock(b.error,b.next||(r.status===401?'/sign-in':'/dashboard'));throw Error(b.error)}return b}async function boot(){if(!await window.AcademyAccess.require())return;const [o,p,l]=await Promise.all([api('overview'),api('provider'),api('learners')]);root.innerHTML=`<p><b>${o.learners} profiles · ${o.staff} staff · ${o.submissions} submissions · ${o.credentials} credentials</b></p><p><a href="/learn">Open review, credentials, support and payment operations</a></p><div class="admin-grid"><section><h2>Email account connection</h2><p>${p.configured?'Connected: '+esc(p.url):'Not connected yet'}. Secure session storage: ${p.secretsConfigured?'ready':'awaiting setup'}.</p><form id="provider"><label>Supabase project URL<input name="url" type="url" required placeholder="https://your-project.supabase.co"></label><label>Publishable key<input name="key" required autocomplete="off" placeholder="sb_publishable_…"></label><button>Connect identity project</button></form><p>Use a publishable key. Enable confirmed email, configure delivery and add this Site to approved redirects. Test registration and recovery before enrolling learners.</p></section><section><h2>Add qualified staff</h2><p>Add your five staff here when ready. A matching confirmed account receives its role after saving its profile. This records an appointment; it does not send an invitation email or change Site sharing.</p><form id="staff"><label>Name<input name="name" required></label><label>Account email<input type="email" name="email" required></label><label>Role<select name="role"><option>Reviewer</option><option>Verifier</option><option>Reviewer and verifier</option></select></label><label>Programme scope<select name="domains" multiple required size="5">${window.ACADEMY_CONTENT.programmes.map(p=>`<option value="${esc(p.id)}">${esc(p.id+' · '+p.title)}</option>`).join('')}</select></label><label>Checked qualification evidence<textarea name="qualification" required minlength="60"></textarea></label><label>Qualification review date<input name="expires" type="date" required></label><button>Record appointment</button></form></section></div><h2>Appointments</h2><div class="admin-table"><table><thead><tr><th>Name</th><th>Role</th><th>Status</th><th>Review date</th></tr></thead><tbody>${o.inviteItems.map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(s.role)}</td><td>${esc(s.status)}</td><td>${esc(s.expires)}</td></tr>`).join('')||'<tr><td colspan="4">No appointments added yet.</td></tr>'}</tbody></table></div><h2>Learner access</h2><div class="admin-table"><table><thead><tr><th>Name</th><th>Email</th><th>Programme</th><th>Status</th><th>Action</th></tr></thead><tbody>${l.items.map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(s.email)}</td><td>${esc(s.goal)}</td><td>${esc(s.status)}</td><td><button data-id="${esc(s.user_id)}" data-status="${s.status==='Active'?'Suspended':'Active'}">${s.status==='Active'?'Suspend':'Restore'}</button></td></tr>`).join('')||'<tr><td colspan="5">No learner profiles yet.</td></tr>'}</tbody></table></div>`;for(const id of ['provider','staff'])root.querySelector('#'+id).onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),b=Object.fromEntries(f);if(id==='staff')b.domains=f.getAll('domains');const button=e.target.querySelector('button');button.disabled=true;try{const r=await api(id==='staff'?'staff-invites':'provider',id==='staff'?'POST':'PUT',b);msg.textContent=r.message;await boot()}catch(e){msg.textContent=e.message}finally{button.disabled=false}};root.querySelectorAll('[data-id]').forEach(button=>button.onclick=async()=>{try{await api('suspend','POST',{userId:button.dataset.id,status:button.dataset.status});await boot()}catch(e){msg.textContent=e.message}});window.ToolIcons.decorate(root);window.AcademyAccess.grant()}boot().catch(e=>window.AcademyAccess.lock(e.message))})();
